Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -20,4 +20,33 @@
 <div class="mobile-controls" aria-label="Movement controls"><button data-dir="up" aria-label="Move up">▲</button><button data-dir="left" aria-label="Move left">◀</button><button data-dir="right" aria-label="Move right">▶</button><button data-dir="down" aria-label="Move down">▼</button></div>
 <footer class="bottom"><div class="chips"><button class="chip" data-prompt="Give me a little red convertible"><span>↗</span>Take a joyride</button><button class="chip" data-prompt="Make it rain, but make it cozy"><span>☂</span>Change the weather</button><button class="chip" data-prompt="Summon a friendly dragon"><span>✦</span>Something magical</button></div><form class="composer" id="commandForm"><span class="spark">✳</span><input id="command" autocomplete="off" placeholder="What would you like to happen?" aria-label="Type anything you want to happen" maxlength="120"/><button class="send" aria-label="Make it happen">↗</button></form><div class="caption">No rules. No quests. Just your imagination. &nbsp;·&nbsp; <span class="key">ENTER</span> to make it real</div></footer>
 <div class="modal-backdrop" id="helpModal"><section class="modal"><button class="icon-btn close" id="closeHelp" aria-label="Close">×</button><div class="eyebrow">Welcome to elsewhere</div><h2>Make a world that feels like yours.</h2><p>Wander somewhere that never ends. Then type whatever you can imagine: a companion, a ride, a change in the sky, a tiny house, or a whole new way to move. There are no wrong answers here.</p><div class="modal-examples"><button data-prompt="Give me a pair of golden wings">“Give me a pair of golden wings”</button><button data-prompt="Build a tiny treehouse nearby">“Build a tiny treehouse nearby”</button><button data-prompt="Teleport me to the ocean">“Teleport me to the ocean”</button></div></section></div>
 <script>
+const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d');
+const player={x:0,y:0,vx:0,vy:0,dir:0,speed:190,fly:false,scale:1,riding:null};
+let W=0,H=0,dpr=1,last=0,clock=0,weather='sunny',timeOfDay=0.77,shake=0;
+const keys=new Set(),things=[],rain=[],toastEl=document.querySelector('#toast');
+const rand=(x,y,n=0)=>{let z=Math.sin(x*127.1+y*311.7+n*74.7)*43758.5453;return z-Math.floor(z)};
+function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
+function pop(msg){toastEl.innerHTML=msg;toastEl.classList.add('show');clearTimeout(pop.timer);pop.timer=setTimeout(()=>toastEl.classList.remove('show'),2500)}
+function say(msg){const el=document.querySelector('#status');el.textContent=msg;el.classList.add('show');clearTimeout(say.timer);say.timer=setTimeout(()=>el.classList.remove('show'),2200)}
+function screen(x,y){return [W/2+x-player.x,H*.53+y-player.y]}
+function pathDistance(x,y){return Math.abs(y-(Math.sin(x*.0014)*125+Math.sin(x*.0031)*37+80))}
+function terrain(){
+ const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#83ae79');g.addColorStop(.58,'#78a66d');g.addColorStop(1,'#6d9a64');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
+ const left=player.x-W/2-160,right=player.x+W/2+160,top=player.y-H*.53-160,bottom=player.y+H*.47+160;
+ for(let gy=Math.floor(top/130);gy<=bottom/130;gy++)for(let gx=Math.floor(left/130);gx<=right/130;gx++){
+  let x=gx*130,y=gy*130,r=rand(gx,gy),[sx,sy]=screen(x,y);
+  ctx.fillStyle=['#a3bc72','#89ae6f','#76a36b','#b0bc78','#759b67'][Math.floor(r*5)];ctx.globalAlpha=.09+r*.08;ctx.beginPath();ctx.ellipse(sx,sy,45+r*60,22+r*34,r*3.1,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
+  if(rand(gx,gy,2)>.35){for(let j=0;j<2;j++){let fx=sx+(rand(gx,gy,j+3)-.5)*110,fy=sy+(rand(gx,gy,j+9)-.5)*70;ctx.fillStyle=rand(gx,gy,j+12)>.5?'#f4df9b':'#f3edc5';ctx.globalAlpha=.5;ctx.beginPath();ctx.arc(fx,fy,1.3,0,7);ctx.fill();ctx.globalAlpha=1}}
+ }
+ // A wandering ochre footpath, repeating into the horizon.
+ ctx.beginPath();let started=false;for(let x=Math.floor(left/18)*18;x<right;x+=18){let y=Math.sin(x*.0014)*125+Math.sin(x*.0031)*37+80,[sx,sy]=screen(x,y);if(!started){ctx.moveTo(sx,sy);started=true}else ctx.lineTo(sx,sy)}
+ ctx.lineWidth=44;ctx.lineCap='round';ctx.strokeStyle='#c1b27b';ctx.globalAlpha=.62;ctx.stroke();ctx.lineWidth=36;ctx.strokeStyle='#d3c28a';ctx.globalAlpha=.78;ctx.stroke();ctx.globalAlpha=1;
+ // A small lake, always discoverable as you roam.
+ const lakeX=420,lakeY=-440,[lx,ly]=screen(lakeX,lakeY);if(lx>-250&&lx<W+250&&ly>-220&&ly<H+220){ctx.fillStyle='#567f72';ctx.beginPath();ctx.ellipse(lx+8,ly+12,170,102,-.2,0,7);ctx.fill();let lg=ctx.createRadialGradient(lx-35,ly-24,8,lx,ly,170);lg.addColorStop(0,'#8dc1ad');lg.addColorStop(1,'#5d9b91');ctx.fillStyle=lg;ctx.beginPath();ctx.ellipse(lx,ly,170,100,-.2,0,7);ctx.fill();ctx.strokeStyle='#dbd69d';ctx.lineWidth=5;ctx.globalAlpha=.55;ctx.stroke();ctx.globalAlpha=1;for(let i=0;i<5;i++){ctx.strokeStyle='#c4e1c4';ctx.globalAlpha=.25;ctx.beginPath();ctx.ellipse(lx-20+i*25,ly-6+i*7,19,3,-.2,0,7);ctx.stroke()}ctx.globalAlpha=1}
+}
+function tree(x,y,size=1,kind=0){const [sx,sy]=screen(x,y),s=size;ctx.save();ctx.translate(sx,sy);ctx.scale(s,s);ctx.fillStyle='#304d3a55';ctx.beginPath();ctx.ellipse(6,7,23,10,0,0,7);ctx.fill();ctx.fillStyle='#6e5138';ctx.fillRect(-3,-25,7,29);ctx.fillStyle=kind?'#4d7650':'#3e704b';ctx.beginPath();ctx.arc(-7,-28,17,0,7);ctx.arc(7,-32,20,0,7);ctx.arc(0,-43,17,0,7);ctx.fill();ctx.fillStyle=kind?'#73925a':'#6e995c';ctx.globalAlpha=.75;ctx.beginPath();ctx.arc(-3,-44,11,0,7);ctx.arc(10,-36,10,0,7);ctx.fill();ctx.restore()}
+function rocks(x,y,size=1){let[sx,sy]=screen(x,y);ctx.fillStyle='#374d3e44';ctx.beginPath();ctx.ellipse(sx+5,sy+4,18*size,8*size,0,0,7);ctx.fill();ctx.fillStyle='#858d79';ctx.beginPath();ctx.ellipse(sx,sy,14*size,9*size,-.2,0,7);ctx.fill();ctx.fillStyle='#a5a58a';ctx.beginPath();ctx.ellipse(sx-4*size,sy-3*size,7*size,3*size,-.3,0,7);ctx.fill()}
+function drawCabin(x,y){let[sx,sy]=screen(x,y);ctx.fillStyle='#324a3b66';ctx.beginPath();ctx.ellipse(sx,sy+10,47,15,0,0,7);ctx.fill();ctx.fillStyle='#c69c69';ctx.fillRect(sx-35,sy-37,70,44);ctx.fillStyle='#634b37';ctx.beginPath();ctx.moveTo(sx-44,sy-35);ctx.lineTo(sx,sy-68);ctx.lineTo(sx+46,sy-35);ctx.closePath();ctx.fill();ctx.fillStyle='#866247';ctx.fillRect(sx-8,sy-23,17,30);ctx.fillStyle='#9fcebb';ctx.fillRect(sx-28,sy-26,12,12);ctx.fillRect(sx+17,sy-26,12,12);ctx.fillStyle='#3c3028';ctx.fillRect(sx-1,sy-7,3,3)}
+function ambientObjects(){const left=player.x-W/2-100,right=player.x+W/2+100,top=player.y-H*.53-100,bottom=player.y+H*.47+100;for(let gy=Math.floor(top/175);gy<=bottom/175;gy++)for(let gx=Math.floor(left/175);gx<=right/175;gx++){let r=rand(gx,gy,22),x=gx*175+rand(gx,gy,1)*145,y=gy*175+rand(gx,gy,2)*145;if(Math.hypot(x-420,y+440)<205)continue;if(pathDistance(x,y)<55)continue;if(r>.18){if(r>.81)rocks(x,y,.6+rand(gx,gy,3)*.65);else tree(x,y,.72+rand(gx,gy,4)*.68,rand(gx,gy,5)>.84?1:0)}}if(Math.hypot(player.x+300,player.y+150)<W+400)drawCabin(-300,-150)}
+function drawPerson(){let[sx,sy]=screen(player.x,player.y);const bob=Math.sin(clock*10)*1.2*Math.min(1,Math.hypot(player.vx,player.vy)/30),sc=player.scale;ctx.save();ctx.translate(sx,sy-bob-(player.fly?18:0));ctx.scale(sc,sc);ctx.fillStyle='#253b3155';ctx.beginPath();ctx.ellipse(4,8,15,8,0,0,7);ctx.fill();if(player.fly){ctx.fillStyle='#eadb9f';ctx.beginPath();ctx.ellipse(-11,-15,17,7,-.55,0,7);ctx.ellipse(12,-15,17,7,.55,0,7);ctx.fill()}ctx.fillStyle='#d99b76';ctx.beginPath();ctx.arc(0,-22,8,0,7);ctx.fill();ctx.fillStyle='#e7e1ca';ctx.beginPath();ctx.arc(-1,-24,8,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#4b7690';ctx.beginPath();ctx.roundRect(-9,-14,18,19,6);ctx.fill();ctx.fillStyle='#dfc7a2';ctx.fillRect(-7,2,5,7);ctx.fillRect(3,2,5,7);ctx.fillStyle='#e9e1d3';ctx.fillRect(-8,7,7,3);ctx.fillRect(2,7,7,3);ctx.save();ctx.rotate(player.dir);ctx.fillStyle='#e2b393';ctx.beginPath();ctx.arc(0,-22,1.4,0,7);ctx.fill();ctx.restore();ctx.restore()}

input.newString:
ctx.restore()}
function drawThing(o){const[sx,sy]=screen(o.x,o.y);ctx.save();ctx.translate(sx,sy);if(o.kind==='car'||o.kind==='bike'){ctx.rotate(o.angle||0);ctx.fillStyle='#182a2470';ctx.beginPath();ctx.ellipse(4,8,o.kind==='car'?33:20,13,0,0,7);ctx.fill();ctx.fillStyle=o.color||'#c95f55';ctx.beginPath();ctx.roundRect(-31,-14,62,29,10);ctx.fill();ctx.fillStyle='#e7e4c8';ctx.beginPath();ctx.roundRect(-12,-10,24,20,6);ctx.fill();ctx.fillStyle='#516d69';ctx.fillRect(-8,-9,16,18);ctx.fillStyle='#f6d990';ctx.fillRect(25,-9,4,6);ctx.fillRect(25,4,4,6);ctx.fillStyle='#303c38';ctx.fillRect(-23,-16,11,3);ctx.fillRect(12,-16,11,3);ctx.fillRect(-23,13,11,3);ctx.fillRect(12,13,11,3)}else if(o.kind==='creature'){const c=o.color||'#e3aa66';ctx.fillStyle='#24392b55';ctx.beginPath();ctx.ellipse(4,9,20,8,0,0,7);ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(0,0,19,12,0,0,7);ctx.fill();ctx.beginPath();ctx.arc(16,-9,10,0,7);ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(11,-16);ctx.lineTo(9,-27);ctx.lineTo(18,-18);ctx.moveTo(20,-17);ctx.lineTo(26,-25);ctx.lineTo(25,-14);ctx.fill();ctx.fillStyle='#fff7da';ctx.beginPath();ctx.arc(19,-10,2.1,0,7);ctx.fill();ctx.fillStyle='#263a2e';ctx.beginPath();ctx.arc(20,-10,1,0,7);ctx.fill();if(o.dragon){ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(-2,-4);ctx.lineTo(-26,-23);ctx.lineTo(-17,-2);ctx.lineTo(-26,5);ctx.lineTo(-3,6);ctx.fill();ctx.fillStyle='#e9cf87';ctx.beginPath();ctx.moveTo(22,-12);ctx.lineTo(36,-18);ctx.lineTo(24,-7);ctx.fill()}}else if(o.kind==='house'||o.kind==='treehouse'){ctx.fillStyle='#354a3670';ctx.fillRect(-28,3,56,8);ctx.fillStyle=o.color||'#c2935b';ctx.fillRect(-24,-27,48,32);ctx.fillStyle='#664b35';ctx.beginPath();ctx.moveTo(-32,-26);ctx.lineTo(0,-49);ctx.lineTo(32,-26);ctx.closePath();ctx.fill();ctx.fillStyle='#8cc0ae';ctx.fillRect(-17,-18,10,10);ctx.fillRect(8,-18,10,10);ctx.fillStyle='#543c2b';ctx.fillRect(-4,-12,9,17);if(o.kind==='treehouse'){ctx.strokeStyle='#7b5435';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-36,8);ctx.lineTo(-36,28);ctx.lineTo(35,28);ctx.stroke();ctx.fillStyle='#715336';ctx.fillRect(-42,-33,5,38)}}else{ctx.fillStyle='#28392c55';ctx.beginPath();ctx.ellipse(3,6,18,8,0,0,7);ctx.fill();ctx.fillStyle=o.color||'#bc9bc9';ctx.beginPath();ctx.ellipse(0,0,15,12,0,0,7);ctx.fill();ctx.beginPath();ctx.arc(12,-7,8,0,7);ctx.fill();ctx.fillStyle='#fff2d6';ctx.beginPath();ctx.arc(15,-9,1.8,0,7);ctx.fill();ctx.fillStyle='#282d23';ctx.beginPath();ctx.arc(16,-9,1,0,7);ctx.fill();if(o.kind==='flower'){ctx.fillStyle='#f4d881';for(let i=0;i<5;i++){ctx.beginPath();ctx.arc(Math.cos(i*1.25)*7,-14+Math.sin(i*1.25)*7,4,0,7);ctx.fill()}}}if(o.label){ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillStyle='#f5f2e7';ctx.shadowColor='#17251d';ctx.shadowBlur=5;ctx.fillText(o.label,0,-38)}ctx.restore()}
function drawWorld(){terrain();ambientObjects();const order=[...things].sort((a,b)=>a.y-b.y);order.forEach(drawThing);if(player.riding){let[sx,sy]=screen(player.x,player.y);ctx.save();ctx.translate(sx,sy);ctx.fillStyle=player.riding.color||'#c95f55';ctx.beginPath();ctx.roundRect(-30,-14,60,28,10);ctx.fill();ctx.fillStyle='#78938a';ctx.beginPath();ctx.roundRect(-10,-10,20,20,6);ctx.fill();ctx.restore()}else drawPerson();
 // Warm late-afternoon light with subtle atmospheric color.
 const tint=ctx.createLinearGradient(0,0,0,H);tint.addColorStop(0,`rgba(246,190,120,${.045+Math.sin(timeOfDay*Math.PI)*.035})`);tint.addColorStop(1,'rgba(24,43,33,.12)');ctx.fillStyle=tint;ctx.fillRect(0,0,W,H);
 if(weather==='rain'||weather==='storm'){for(const d of rain){d.x-=d.vx;d.y+=d.vy;if(d.y>H){d.y=-10;d.x=Math.random()*W}ctx.strokeStyle=weather==='storm'?'#d7e5df88':'#d8e9df77';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(d.x,d.y);ctx.lineTo(d.x-4,d.y+12);ctx.stroke()}}
 if(weather==='snow'){for(let i=0;i<55;i++){let x=(i*173+clock*10)%W,y=(i*97+clock*24)%H;ctx.fillStyle='#fff9e8a8';ctx.beginPath();ctx.arc(x,y,1.5+(i%3),0,7);ctx.fill()}}
 if(weather==='storm'&&Math.sin(clock*1.7)>.995){ctx.fillStyle='#e7f2e888';ctx.fillRect(0,0,W,H)}
}
function loop(t){const dt=Math.min(.04,(t-last)/1000||0);last=t;clock+=dt;let ax=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),ay=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);let mag=Math.hypot(ax,ay)||1;ax/=mag;ay/=mag;let speed=player.speed*(player.riding?2.45:1)*(player.fly?1.28:1);player.vx+=(ax*speed-player.vx)*Math.min(1,dt*8);player.vy+=(ay*speed-player.vy)*Math.min(1,dt*8);player.x+=player.vx*dt;player.y+=player.vy*dt;if(Math.hypot(player.vx,player.vy)>3)player.dir=Math.atan2(player.vy,player.vx);if(!ax&&!ay){player.vx*=Math.pow(.02,dt);player.vy*=Math.pow(.02,dt)}drawWorld();document.querySelector('#coords').innerHTML=`${Math.abs(Math.round(player.y/100))}° ${player.y<0?'N':'S'} &nbsp; ${Math.abs(Math.round(player.x/100))}° ${player.x<0?'W':'E'}`;requestAnimationFrame(loop)}
for(let i=0;i<110;i++)rain.push({x:Math.random()*innerWidth,y:Math.random()*innerHeight,vx:2+Math.random()*2,vy:9+Math.random()*8});
const keymap={w:'w',a:'a',s:'s',d:'d',arrowup:'arrowup',arrowdown:'arrowdown',arrowleft:'arrowleft',arrowright:'arrowright'};addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(keymap[k]){keys.add(keymap[k]);if(k.startsWith('arrow'))e.preventDefault()}if(k==='enter'&&document.activeElement!==document.querySelector('#command'))document.querySelector('#command').focus();if(k==='e'){if(player.riding){player.riding=null;say('You hop out, just to feel the grass.')}else{const car=things.find(o=>(o.kind==='car'||o.kind==='bike')&&Math.hypot(o.x-player.x,o.y-player.y)<95);if(car){player.riding=car;say('Hop in. The whole world is the open road.')}else{const pal=things.find(o=>o.kind==='creature'&&Math.hypot(o.x-player.x,o.y-player.y)<90);if(pal)say(`${pal.label||'Your friend'} nuzzles your hand.`);else say('A quiet breeze brushes through the grass.')}}}});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>keys.clear());document.querySelectorAll('.mobile-controls button').forEach(b=>{const dir=b.dataset.dir,down=e=>{e.preventDefault();keys.add(({up:'w',down:'s',left:'a',right:'d'})[dir]);b.setPointerCapture?.(e.pointerId)},up=e=>{e.preventDefault();keys.delete(({up:'w',down:'s',left:'a',right:'d'})[dir])};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up)});

ctx.save();ctx.rotate(player.dir);ctx.fillStyle='#e2b393';ctx.beginPath();ctx.arc(0,-22,1.4,0,7);ctx.fill();ctx.restore();ctx.restore()}
function drawThing(o){const[sx,sy]=screen(o.x,o.y);ctx.save();ctx.translate(sx,sy);if(o.kind==='car'||o.kind==='bike'){ctx.rotate(o.angle||0);ctx.fillStyle='#182a2470';ctx.beginPath();ctx.ellipse(4,8,o.kind==='car'?33:20,13,0,0,7);ctx.fill();ctx.fillStyle=o.color||'#c95f55';ctx.beginPath();ctx.roundRect(-31,-14,62,29,10);ctx.fill();ctx.fillStyle='#e7e4c8';ctx.beginPath();ctx.roundRect(-12,-10,24,20,6);ctx.fill();ctx.fillStyle='#516d69';ctx.fillRect(-8,-9,16,18);ctx.fillStyle='#f6d990';ctx.fillRect(25,-9,4,6);ctx.fillRect(25,4,4,6);ctx.fillStyle='#303c38';ctx.fillRect(-23,-16,11,3);ctx.fillRect(12,-16,11,3);ctx.fillRect(-23,13,11,3);ctx.fillRect(12,13,11,3)}else if(o.kind==='creature'){const c=o.color||'#e3aa66';ctx.fillStyle='#24392b55';ctx.beginPath();ctx.ellipse(4,9,20,8,0,0,7);ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(0,0,19,12,0,0,7);ctx.fill();ctx.beginPath();ctx.arc(16,-9,10,0,7);ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(11,-16);ctx.lineTo(9,-27);ctx.lineTo(18,-18);ctx.moveTo(20,-17);ctx.lineTo(26,-25);ctx.lineTo(25,-14);ctx.fill();ctx.fillStyle='#fff7da';ctx.beginPath();ctx.arc(19,-10,2.1,0,7);ctx.fill();ctx.fillStyle='#263a2e';ctx.beginPath();ctx.arc(20,-10,1,0,7);ctx.fill();if(o.dragon){ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(-2,-4);ctx.lineTo(-26,-23);ctx.lineTo(-17,-2);ctx.lineTo(-26,5);ctx.lineTo(-3,6);ctx.fill();ctx.fillStyle='#e9cf87';ctx.beginPath();ctx.moveTo(22,-12);ctx.lineTo(36,-18);ctx.lineTo(24,-7);ctx.fill()}}else if(o.kind==='house'||o.kind==='treehouse'){ctx.fillStyle='#354a3670';ctx.fillRect(-28,3,56,8);ctx.fillStyle=o.color||'#c2935b';ctx.fillRect(-24,-27,48,32);ctx.fillStyle='#664b35';ctx.beginPath();ctx.moveTo(-32,-26);ctx.lineTo(0,-49);ctx.lineTo(32,-26);ctx.closePath();ctx.fill();ctx.fillStyle='#8cc0ae';ctx.fillRect(-17,-18,10,10);ctx.fillRect(8,-18,10,10);ctx.fillStyle='#543c2b';ctx.fillRect(-4,-12,9,17);if(o.kind==='treehouse'){ctx.strokeStyle='#7b5435';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-36,8);ctx.lineTo(-36,28);ctx.lineTo(35,28);ctx.stroke();ctx.fillStyle='#715336';ctx.fillRect(-42,-33,5,38)}}else{ctx.fillStyle='#28392c55';ctx.beginPath();ctx.ellipse(3,6,18,8,0,0,7);ctx.fill();ctx.fillStyle=o.color||'#bc9bc9';ctx.beginPath();ctx.ellipse(0,0,15,12,0,0,7);ctx.fill();ctx.beginPath();ctx.arc(12,-7,8,0,7);ctx.fill();ctx.fillStyle='#fff2d6';ctx.beginPath();ctx.arc(15,-9,1.8,0,7);ctx.fill();ctx.fillStyle='#282d23';ctx.beginPath();ctx.arc(16,-9,1,0,7);ctx.fill();if(o.kind==='flower'){ctx.fillStyle='#f4d881';for(let i=0;i<5;i++){ctx.beginPath();ctx.arc(Math.cos(i*1.25)*7,-14+Math.sin(i*1.25)*7,4,0,7);ctx.fill()}}}if(o.label){ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillStyle='#f5f2e7';ctx.shadowColor='#17251d';ctx.shadowBlur=5;ctx.fillText(o.label,0,-38)}ctx.restore()}
function drawWorld(){terrain();ambientObjects();const order=[...things].sort((a,b)=>a.y-b.y);order.forEach(drawThing);if(player.riding){let[sx,sy]=screen(player.x,player.y);ctx.save();ctx.translate(sx,sy);ctx.fillStyle=player.riding.color||'#c95f55';ctx.beginPath();ctx.roundRect(-30,-14,60,28,10);ctx.fill();ctx.fillStyle='#78938a';ctx.beginPath();ctx.roundRect(-10,-10,20,20,6);ctx.fill();ctx.restore()}else drawPerson();
 const tint=ctx.createLinearGradient(0,0,0,H);tint.addColorStop(0,`rgba(246,190,120,${.045+Math.sin(timeOfDay*Math.PI)*.035})`);tint.addColorStop(1,'rgba(24,43,33,.12)');ctx.fillStyle=tint;ctx.fillRect(0,0,W,H);
 if(weather==='rain'||weather==='storm'){for(const d of rain){d.x-=d.vx;d.y+=d.vy;if(d.y>H){d.y=-10;d.x=Math.random()*W}ctx.strokeStyle=weather==='storm'?'#d7e5df88':'#d8e9df77';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(d.x,d.y);ctx.lineTo(d.x-4,d.y+12);ctx.stroke()}}
 if(weather==='snow'){for(let i=0;i<55;i++){let x=(i*173+clock*10)%W,y=(i*97+clock*24)%H;ctx.fillStyle='#fff9e8a8';ctx.beginPath();ctx.arc(x,y,1.5+(i%3),0,7);ctx.fill()}}
